adcs_vec3_t b, p, mapped, ref_n;
double dot, clamped, nrm;
if ((c == NULL) || (body == NULL) || (reference == NULL) || (innovation == NULL) || (angle == NULL))
    return ADCS_E_NULL;

if (!adcs_is_finite_vec3(body) || !adcs_is_finite_vec3(reference)) {
    *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
    *angle = INFINITY;
    return ADCS_E_RANGE;
}

if (adcs_vec3_normalize(body, ADCS_EPS_NORM, &b) != ADCS_OK) {
    *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
    *angle = INFINITY;
    return ADCS_E_RANGE;
}

if (adcs_vec3_normalize(reference, ADCS_EPS_NORM, &ref_n) != ADCS_OK) {
    *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
    *angle = INFINITY;
    return ADCS_E_RANGE;
}

mapped = adcs_mat3_mul_vec(c, &ref_n);
if ((!adcs_is_finite_vec3(&mapped)) ||
    (adcs_vec3_normalize(&mapped, ADCS_EPS_NORM, &p) != ADCS_OK)) {
    *innovation = (adcs_vec3_t){0.0, 0.0, 0.0};
    *angle = INFINITY;
    return ADCS_E_RANGE;
}

*innovation = adcs_vec3_cross(&b, &p);
dot = adcs_vec3_dot(&b, &p);
clamped = ADCS_CLAMP(dot, -1.0, 1.0);
nrm = adcs_vec3_norm(innovation);
*angle = atan2(nrm, clamped);
return ADCS_OK;
}

